package com.nyayaconnect.web;
import com.nyayaconnect.auth.SpringAccess;import com.nyayaconnect.common.Api;import com.nyayaconnect.security.AuthenticationFilter;import com.nyayaconnect.security.SessionUser;import jakarta.servlet.http.*;import org.springframework.jdbc.core.JdbcTemplate;import java.io.IOException;import java.util.Map;import java.util.UUID;
public final class NotificationServlet extends HttpServlet { private JdbcTemplate db; public void init(){db=SpringAccess.bean(getServletContext(),JdbcTemplate.class);}
 protected void doPatch(HttpServletRequest req,HttpServletResponse res)throws IOException{try{SessionUser u=(SessionUser)req.getSession(false).getAttribute(AuthenticationFilter.SESSION_KEY);String[] p=req.getPathInfo().split("/");UUID id=UUID.fromString(p[p.length-1]);int n=db.update("update notifications set read_at=coalesce(read_at,CURRENT_TIMESTAMP) where id=? and user_id=?",id.toString(),u.id().toString());if(n!=1)throw new SecurityException("Notification not found or not owned by current user.");Api.json(res,200,Map.of("status","READ","id",id));}catch(SecurityException e){Api.error(res,403,"FORBIDDEN",e.getMessage());}catch(Exception e){Api.error(res,400,"INVALID_REQUEST","Invalid notification request.");}}
}
